html:
{%- set MESES = ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"] -%}
{%- set DIAS = ["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"] -%}
{%- set paroquia = frappe.db.get_single_value("Catequese Settings", "paroquia") or "" -%}
{%- set ministerio = frappe.db.get_single_value("Catequese Settings", "ministerio") or "" -%}
<style>
  .pp { font-family: Arial, Helvetica, sans-serif; color: #1f2937; font-size: 10.5px; }
  .pp-head { text-align: center; margin-bottom: 14px; }
  .pp-head .l1 { font-size: 11px; font-weight: 700; letter-spacing: .02em; }
  .pp-head .l2 { font-size: 10px; color: #4b5563; margin-top: 2px; }
  .pp-head h1 { font-size: 17px; margin: 10px 0 2px; }
  .pp-estado { display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 9.5px; font-weight: 700;
               border: 1px solid #9ca3af; color: #4b5563; }
  .pp-estado.final { border-color: #16a34a; color: #16a34a; }
  .pp-meta { font-size: 9.5px; color: #6b7280; margin-top: 4px; }
  .pp table { width: 100%; border-collapse: collapse; margin-bottom: 10px; page-break-inside: auto; }
  .pp th { background: #eef2ff; color: #312e81; text-align: left; font-size: 9.5px; text-transform: uppercase;
           letter-spacing: .03em; padding: 5px 6px; border: 1px solid #c7d2fe; }
  .pp td { padding: 5px 6px; border: 1px solid #d1d5db; vertical-align: top; }
  .pp tr { page-break-inside: avoid; }
  .pp .mes td { background: #312e81; color: #fff; font-weight: 700; font-size: 10.5px; border-color: #312e81; }
  .pp .data { white-space: nowrap; width: 72px; }
  .pp .dia { color: #6b7280; font-size: 9px; }
  .pp .nova { color: #7c3aed; font-size: 8.5px; font-weight: 700; }
  .pp .notas { width: 26%; }
  .pp .notas-impressas { color: #374151; font-style: italic; }
  .pp-rodape { margin-top: 12px; font-size: 9.5px; color: #4b5563; }
  .pp-gerais { margin-top: 10px; padding: 8px 10px; border: 1px solid #d1d5db; border-radius: 6px; }
</style>

<div class="pp">
  <div class="pp-head">
    <div class="l1">{{ paroquia }}</div>
    <div class="l2">{{ ministerio }}</div>
    <h1>Proposta do Plano Anual {{ doc.ano_destino }}</h1>
    {% if doc.docstatus == 1 %}
      <span class="pp-estado final">FINALIZADA</span>
    {% else %}
      <span class="pp-estado">RASCUNHO PARA DISCUSSÃO</span>
    {% endif %}
    <div class="pp-meta">
      {{ doc.itens | length }} actividades
      {% if doc.ano_origem %} · baseada no plano de {{ doc.ano_origem }}{% endif %}
      · impresso em {{ frappe.utils.formatdate(frappe.utils.nowdate(), "dd/MM/yyyy") }}
    </div>
  </div>

  <table>
    <thead>
      <tr>
        <th class="data">Data</th>
        <th>Actividade</th>
        <th>Tipologia</th>
        <th>Local</th>
        <th>Responsável</th>
        <th class="notas">Notas</th>
      </tr>
    </thead>
    <tbody>
      {%- set ns = namespace(mes=-1) -%}
      {%- for it in doc.itens -%}
        {%- set d = frappe.utils.getdate(it.data) if it.data else None -%}
        {%- set m = (d.month - 1) if d else 12 -%}
        {%- if m != ns.mes -%}
          {%- set ns.mes = m -%}
          <tr class="mes"><td colspan="6">{{ MESES[m] if m < 12 else "Sem data" }}</td></tr>
        {%- endif %}
        <tr>
          <td class="data">
            {% if d %}{{ d.strftime("%d/%m") }}{% if it.data_fim and it.data_fim != it.data %}–{{ frappe.utils.getdate(it.data_fim).strftime("%d/%m") }}{% endif %}
            <div class="dia">{{ DIAS[d.weekday()] }}</div>{% else %}—{% endif %}
          </td>
          <td>{{ it.actividade }}{% if it.origem == "Nova" %} <span class="nova">NOVA</span>{% endif %}</td>
          <td>{{ it.tipologia or "" }}</td>
          <td>{{ it.local or "" }}</td>
          <td>{{ it.orador or "" }}</td>
          <td class="notas">{% if it.notas %}<span class="notas-impressas">{{ it.notas }}</span>{% endif %}</td>
        </tr>
      {%- endfor %}
    </tbody>
  </table>

  {% if doc.notas %}
    <div class="pp-gerais"><b>Notas gerais:</b> {{ doc.notas }}</div>
  {% endif %}
  <div class="pp-rodape">{{ doc.name }}</div>
</div>
